using Microsoft.EntityFrameworkCore;

public sealed class CancelOrderHandler(ShopDb db, IEventBus bus)
{
    public async Task Handle(int orderId, CancellationToken ct)
    {
        var order = await db.Orders.SingleAsync(o => o.Id == orderId, ct);
        order.Cancel();
        await db.SaveChangesAsync(ct);
        // A second write, outside the transaction: if it fails, reads never learn
        await bus.PublishAsync(new OrderCancelled(orderId), ct);
    }
}

public sealed class OrderListQuery(IReadStore reads)
{
    // A copy that a projector updates later, so it can miss the user's change
    public Task<List<OrderRow>> Run(int customerId, CancellationToken ct) =>
        reads.OrdersFor(customerId, ct);
}

using Microsoft.EntityFrameworkCore;

// Command side: load the entity, let it enforce the rule, save
public sealed class CancelOrderHandler(ShopDb db)
{
    public async Task Handle(int orderId, CancellationToken ct)
    {
        var order = await db.Orders.SingleAsync(o => o.Id == orderId, ct);
        order.Cancel(); // throws if the order has shipped
        await db.SaveChangesAsync(ct);
    }
}

// Query side: same database, no domain model, only what the screen shows
public sealed class OrderListQuery(ShopDb db)
{
    public Task<List<OrderRow>> Run(int customerId, CancellationToken ct) =>
        db.Orders.Where(o => o.CustomerId == customerId)
            .OrderByDescending(o => o.PlacedAt)
            .Select(o => new OrderRow(o.Id, o.PlacedAt, o.Status))
            .ToListAsync(ct);
}
